/** Used when no role above fits: content is built around the role name and the job post's keywords. */
export function genericRole(title: string, kws: string[]): RoleProfile {
  const t = title || 'Professional';
  const k = (i: number, fb: string) => kws[i] ?? fb;
  return {
    id: 'generic', title: t, match: /$^/, degree: "[Bachelor's Degree in Your Subject]", link: null,
    coursework: 'Business Communication, Computer Applications, Management Basics',
    skills: kws.length ? kws.slice(0, 16) : ['Microsoft Excel', 'Google Workspace', 'Reporting', 'Documentation', 'Data Entry', 'ChatGPT', 'Customer Service', 'Time Management', 'Microsoft PowerPoint', 'Planning'],
    soft: ['Communication', 'Teamwork', 'Problem Solving', 'Time Management'],
    duties: [`Handle day-to-day ${t} tasks with accuracy.`, `Use ${k(0, 'Microsoft Excel')} and ${k(1, 'Google Workspace')} for reporting and documentation.`, 'Work with the team to improve processes and results.', 'Share clear updates with managers and stakeholders.'],
    projects: [
      { title: `${t} Process Improvement Project`, tools: [k(0, 'Microsoft Excel'), k(1, 'Process Mapping'), 'Documentation'].join(', '), points: [`Mapped a [10]-step ${t.toLowerCase()} process and identified [3] steps to simplify.`, `Applied ${k(0, 'Microsoft Excel')} to track results, cutting manual work by [30%].`, 'Presented the plan to a [mentor or faculty panel] with clear next steps.'] },
      { title: `${t} Performance Report`, tools: [k(2, 'Reporting'), k(3, 'Google Sheets'), 'Dashboards'].join(', '), points: [`Analyzed [6] months of ${t.toLowerCase()} data using ${k(2, 'reporting')} tools.`, `Built a simple dashboard with [8] KPIs that saved [4 hours] of reporting a week.`, `Identified [3] ways to improve ${k(3, 'quality')} and shared them with the team.`] },
      { title: 'Community Volunteer Initiative', tools: [k(4, 'Planning'), 'Coordination', 'Communication'].join(', '), points: ['Organized a volunteer drive with [25] members that served [300+] people.', `Coordinated schedules and ${k(4, 'planning')} for [4] weekend events.`, 'Raised [₹50,000] in donations through local outreach.'] },
    ],
    work: [`Delivered daily ${t.toLowerCase()} work for [50+] clients or customers with [98%] accuracy.`, `Improved ${k(0, 'reporting')} processes, saving [5 hours] a week.`, `Collaborated with [3] teams to complete [20+] tasks on time each month.`, 'Trained [4] new team members on tools and processes.'],
    certs: ['Microsoft Office Specialist: Excel', 'LinkedIn Learning: Business Communication'],
    achievements: ['Received a [certificate of merit] for [your achievement].', 'Led a [college club or volunteer team] of [15] members.'],
    interests: 'Reading, Volunteering, Sports',
  };
}

